                printf("Result: %d\n", subtract(&num1));
                break;
            case MULTIPLICATION:
                printf("Result: %d\n", multiply(&num1));
                break;
            case DIVISION:
                if (divide(&num1)) {
                    printf("Result: %d\n", divide(&num1));
                } else {
                    printf("Error: Division by zero\n");
                }
                break;
            default:
                printf("Unsupported operation\n");
        }
    } else {
        // Interactive mode implementation here...
    }

    return 0;
}
